-- ============================================================
-- 次元放映室 · MySQL 唯一数据库脚本
-- ============================================================
-- 文件位置：database/acgn_screenroom.sql
-- 执行账号：root / root
-- 数据库端口：3307（非默认端口；MySQL X Protocol 33070）
-- 执行命令（PowerShell）：Get-Content -Raw -Encoding UTF8 .\database\acgn_screenroom.sql | & 'C:\Program Files\MySQL\MySQL Server 26.10\bin\mysql.exe' -u root -proot -P 3307 --protocol=TCP --default-character-set=utf8mb4
--
-- 使用说明：
-- 1. 本文件同时包含「建库建表」「旧库升级」「种子数据」「评分回算」「管理查询」五部分。
-- 2. 新库直接执行即可；旧库重复执行也不会重复插入种子数据。
-- 3. 所有番剧分数均来自 ratings 表中的真实用户评分，脚本不写入虚构评分人数。
-- 4. 文件末尾附带常用管理查询，默认全部注释，不会自动执行。
-- ============================================================

-- ------------------------------------------------------------
-- 第 1 部分：数据库与表结构
-- ------------------------------------------------------------

CREATE DATABASE IF NOT EXISTS acgn_screenroom
  DEFAULT CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

USE acgn_screenroom;

-- 1.1 用户表：登录账号、角色与明文密码（本地演示库）
CREATE TABLE IF NOT EXISTS users (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '用户 ID',
  username VARCHAR(40) NOT NULL UNIQUE COMMENT '登录用户名',
  nickname VARCHAR(60) NOT NULL COMMENT '用户昵称，评论展示用',
  email VARCHAR(120) NOT NULL UNIQUE COMMENT '邮箱',
  password VARCHAR(255) NOT NULL COMMENT '明文密码（演示库，未加密）',
  role ENUM('USER','ADMIN') NOT NULL DEFAULT 'USER' COMMENT '角色：普通用户 / 管理员',
  avatar_url VARCHAR(500) COMMENT '头像地址',
  bio VARCHAR(255) COMMENT '个人简介',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间'
) ENGINE=InnoDB COMMENT='用户表';

-- 1.2 作品表：番剧 / 电影基础信息
-- 注意：score 与 score_count 是 ratings 表的聚合缓存，由本脚本末尾统一回算。
CREATE TABLE IF NOT EXISTS anime (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '作品 ID',
  title VARCHAR(160) NOT NULL COMMENT '作品中文名',
  original_title VARCHAR(160) COMMENT '作品原名',
  summary TEXT COMMENT '剧情简介',
  cover_url VARCHAR(500) COMMENT '封面图片 URL，后台可修改',
  pv_url VARCHAR(500) COMMENT '预览地址（Bilibili 视频 / 番剧链接 / BV、av 号），后台可修改',
  season VARCHAR(30) COMMENT '季度，如 2026 夏',
  media_type ENUM('ANIME','MOVIE') NOT NULL DEFAULT 'ANIME' COMMENT '作品类型：番剧 / 电影',
  status ENUM('AIRING','FINISHED','UPCOMING') NOT NULL DEFAULT 'UPCOMING' COMMENT '播出状态',
  score DECIMAL(3,1) NOT NULL DEFAULT 0 COMMENT '真实用户评分均分，由 ratings 回算',
  score_count INT NOT NULL DEFAULT 0 COMMENT '真实评分人数，由 ratings 回算',
  sort_order INT NOT NULL DEFAULT 0 COMMENT '展示顺序，同系列作品连续排列',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '收录时间',
  INDEX idx_anime_season (season),
  INDEX idx_anime_score (score),
  INDEX idx_anime_sort (sort_order)
) ENGINE=InnoDB COMMENT='番剧与电影作品表';

-- 1.3 标签表与作品-标签关联表
CREATE TABLE IF NOT EXISTS genres (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '标签 ID',
  name VARCHAR(40) NOT NULL UNIQUE COMMENT '标签名称'
) ENGINE=InnoDB COMMENT='作品标签表';

CREATE TABLE IF NOT EXISTS anime_genres (
  anime_id BIGINT NOT NULL COMMENT '作品 ID',
  genre_id BIGINT NOT NULL COMMENT '标签 ID',
  PRIMARY KEY (anime_id, genre_id),
  FOREIGN KEY (anime_id) REFERENCES anime(id) ON DELETE CASCADE,
  FOREIGN KEY (genre_id) REFERENCES genres(id) ON DELETE CASCADE
) ENGINE=InnoDB COMMENT='作品与标签多对多关联表';

-- 1.4 评分表：真实评分的唯一数据源
-- 唯一约束保证「一个用户一部作品只有一条评分」。
CREATE TABLE IF NOT EXISTS ratings (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '评分 ID',
  user_id BIGINT NOT NULL COMMENT '评分用户 ID',
  anime_id BIGINT NOT NULL COMMENT '被评分作品 ID',
  score TINYINT NOT NULL COMMENT '用户评分，范围 1–10',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '评分 / 修改时间',
  UNIQUE KEY uk_user_anime_rating (user_id, anime_id),
  KEY idx_ratings_anime (anime_id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (anime_id) REFERENCES anime(id) ON DELETE CASCADE,
  CHECK (score BETWEEN 1 AND 10)
) ENGINE=InnoDB COMMENT='用户真实评分表';

-- 1.5 评论表：详情页评论与后台审核的数据源
CREATE TABLE IF NOT EXISTS comments (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '评论 ID',
  user_id BIGINT NOT NULL COMMENT '评论用户 ID',
  anime_id BIGINT NOT NULL COMMENT '所属作品 ID',
  content VARCHAR(1000) NOT NULL COMMENT '评论内容',
  likes INT NOT NULL DEFAULT 0 COMMENT '点赞数',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '发表时间',
  KEY idx_comments_anime_time (anime_id, created_at),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (anime_id) REFERENCES anime(id) ON DELETE CASCADE
) ENGINE=InnoDB COMMENT='作品评论表';

-- 1.6 追番片单表：想看 / 在看 / 看过，一个用户一部作品只有一条记录
CREATE TABLE IF NOT EXISTS watchlist (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '片单记录 ID',
  user_id BIGINT NOT NULL COMMENT '用户 ID',
  anime_id BIGINT NOT NULL COMMENT '作品 ID',
  status ENUM('WANT','WATCHING','WATCHED') NOT NULL DEFAULT 'WANT' COMMENT '观看状态',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '加入时间',
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '状态更新时间',
  UNIQUE KEY uk_user_anime_watchlist (user_id, anime_id),
  KEY idx_watchlist_user_status (user_id, status),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (anime_id) REFERENCES anime(id) ON DELETE CASCADE
) ENGINE=InnoDB COMMENT='用户追番片单表';

-- 1.7 评论点赞表：记录用户与评论的一对一点赞关系，防止重复点赞
CREATE TABLE IF NOT EXISTS comment_likes (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '点赞 ID',
  user_id BIGINT NOT NULL COMMENT '点赞用户 ID',
  comment_id BIGINT NOT NULL COMMENT '被点赞评论 ID',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '点赞时间',
  UNIQUE KEY uk_user_comment_like (user_id, comment_id),
  KEY idx_comment_likes_comment (comment_id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (comment_id) REFERENCES comments(id) ON DELETE CASCADE
) ENGINE=InnoDB COMMENT='评论点赞记录表';

-- 1.8 登录令牌表：服务端签发 / 校验 Bearer Token
CREATE TABLE IF NOT EXISTS auth_tokens (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '令牌 ID',
  user_id BIGINT NOT NULL COMMENT '所属用户 ID',
  token_hash VARCHAR(128) NOT NULL UNIQUE COMMENT '令牌 SHA-256 哈希，不存明文',
  expires_at TIMESTAMP NOT NULL COMMENT '过期时间，默认 7 天',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '签发时间',
  KEY idx_auth_tokens_user (user_id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB COMMENT='登录令牌表';

-- 1.9 漫评表：与番剧绑定的长评，区别于作品详情页短评论
CREATE TABLE IF NOT EXISTS reviews (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '漫评 ID',
  user_id BIGINT NOT NULL COMMENT '作者用户 ID',
  anime_id BIGINT NOT NULL COMMENT '关联作品 ID',
  title VARCHAR(160) NOT NULL COMMENT '漫评标题',
  content TEXT NOT NULL COMMENT '漫评正文',
  score INT NOT NULL COMMENT '作者打分 1–10',
  likes INT NOT NULL DEFAULT 0 COMMENT '点赞数',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '发表时间',
  KEY idx_reviews_created (created_at),
  KEY idx_reviews_anime (anime_id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (anime_id) REFERENCES anime(id) ON DELETE CASCADE,
  CHECK (score BETWEEN 1 AND 10)
) ENGINE=InnoDB COMMENT='长篇漫评表';

-- 1.10 漫评点赞表
CREATE TABLE IF NOT EXISTS review_likes (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '点赞 ID',
  user_id BIGINT NOT NULL COMMENT '用户 ID',
  review_id BIGINT NOT NULL COMMENT '漫评 ID',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '点赞时间',
  UNIQUE KEY uk_user_review_like (user_id, review_id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (review_id) REFERENCES reviews(id) ON DELETE CASCADE
) ENGINE=InnoDB COMMENT='漫评点赞表';

-- 1.11 社群内容表：话题 / 小组 / 放映会统一存放
CREATE TABLE IF NOT EXISTS community_items (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '内容 ID',
  kind ENUM('TOPIC','GROUP','EVENT') NOT NULL COMMENT '内容类型',
  title VARCHAR(160) NOT NULL COMMENT '标题或名称',
  description TEXT COMMENT '简介 / 首条发言 / 活动说明',
  tag VARCHAR(80) COMMENT '标签或时间',
  color VARCHAR(20) DEFAULT 'pink' COMMENT '主题色 pink / blue / black',
  base_count INT NOT NULL DEFAULT 0 COMMENT '展示基数（与真实成员 / 回复数相加后展示）',
  user_id BIGINT COMMENT '创建者 ID',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  KEY idx_community_kind (kind),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB COMMENT='社群话题、小组与放映会表';

-- 1.12 社群成员表：加入小组 / 报名放映会
CREATE TABLE IF NOT EXISTS community_item_members (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '记录 ID',
  user_id BIGINT NOT NULL COMMENT '用户 ID',
  item_id BIGINT NOT NULL COMMENT '小组或放映会 ID',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '加入时间',
  UNIQUE KEY uk_community_item_member (user_id, item_id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (item_id) REFERENCES community_items(id) ON DELETE CASCADE
) ENGINE=InnoDB COMMENT='社群成员与活动报名表';

-- 1.13 话题回复表
CREATE TABLE IF NOT EXISTS topic_posts (
  id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '回复 ID',
  item_id BIGINT NOT NULL COMMENT '话题 ID',
  user_id BIGINT NOT NULL COMMENT '回复用户 ID',
  content VARCHAR(1000) NOT NULL COMMENT '回复内容',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '回复时间',
  KEY idx_topic_posts_item (item_id, created_at),
  FOREIGN KEY (item_id) REFERENCES community_items(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB COMMENT='社群话题回复表';

-- ------------------------------------------------------------
-- 第 2 部分：旧库结构升级
-- 用 information_schema 判断列是否存在，已升级的库会跳过对应 ALTER。
-- ------------------------------------------------------------

-- 2.1 users 表补列
SET @has_role = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'users' AND column_name = 'role');
SET @sql = IF(@has_role = 0, 'ALTER TABLE users ADD COLUMN role ENUM(''USER'',''ADMIN'') NOT NULL DEFAULT ''USER'' AFTER email', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @has_nickname = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'users' AND column_name = 'nickname');
SET @sql = IF(@has_nickname = 0, 'ALTER TABLE users ADD COLUMN nickname VARCHAR(60) NULL AFTER username', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
UPDATE users SET nickname = username WHERE nickname IS NULL OR nickname = '';
ALTER TABLE users MODIFY nickname VARCHAR(60) NOT NULL COMMENT '用户昵称，评论展示用';

SET @has_avatar = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'users' AND column_name = 'avatar_url');
SET @sql = IF(@has_avatar = 0, 'ALTER TABLE users ADD COLUMN avatar_url VARCHAR(500) NULL', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @has_bio = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'users' AND column_name = 'bio');
SET @sql = IF(@has_bio = 0, 'ALTER TABLE users ADD COLUMN bio VARCHAR(255) NULL', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @has_user_created = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'users' AND column_name = 'created_at');
SET @sql = IF(@has_user_created = 0, 'ALTER TABLE users ADD COLUMN created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 2.1.1 旧库密码列改为明文列
SET @has_password = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'users' AND column_name = 'password');
SET @has_password_hash = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'users' AND column_name = 'password_hash');
SET @sql = IF(@has_password_hash = 1 AND @has_password = 0, 'ALTER TABLE users CHANGE COLUMN password_hash password VARCHAR(255) NOT NULL COMMENT ''明文密码（演示库，未加密）''', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql = IF(@has_password = 0 AND @has_password_hash = 0, 'ALTER TABLE users ADD COLUMN password VARCHAR(255) NOT NULL DEFAULT ''demo123'' AFTER email', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
-- 2.2 anime 表补列
SET @has_media_type = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'anime' AND column_name = 'media_type');
SET @sql = IF(@has_media_type = 0, 'ALTER TABLE anime ADD COLUMN media_type ENUM(''ANIME'',''MOVIE'') NOT NULL DEFAULT ''ANIME'' AFTER season', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @has_summary = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'anime' AND column_name = 'summary');
SET @sql = IF(@has_summary = 0, 'ALTER TABLE anime ADD COLUMN summary TEXT NULL AFTER original_title', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @has_anime_created = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'anime' AND column_name = 'created_at');
SET @sql = IF(@has_anime_created = 0, 'ALTER TABLE anime ADD COLUMN created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @has_sort_order = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'anime' AND column_name = 'sort_order');
SET @sql = IF(@has_sort_order = 0, 'ALTER TABLE anime ADD COLUMN sort_order INT NOT NULL DEFAULT 0 COMMENT ''展示顺序，同系列作品连续排列'' AFTER score_count', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 2.2.1 统一 reviews.score 为 INT，匹配 JPA Integer 类型校验
ALTER TABLE reviews MODIFY score INT NOT NULL COMMENT '作者打分 1–10';

-- 2.2.2 同步旧库字段注释，使其与当前明文密码、Bilibili 预览与社群真实计数口径一致
ALTER TABLE users MODIFY password VARCHAR(255) NOT NULL COMMENT '明文密码（演示库，未加密）';
ALTER TABLE anime MODIFY pv_url VARCHAR(500) COMMENT '预览地址（Bilibili 视频 / 番剧链接 / BV、av 号），后台可修改';
ALTER TABLE community_items MODIFY base_count INT NOT NULL DEFAULT 0 COMMENT '展示基数（与真实成员 / 回复数相加后展示）';

-- 2.3 修正历史空角色
UPDATE users SET role = 'USER' WHERE role IS NULL OR role = '';

-- ------------------------------------------------------------
-- 第 3 部分：种子数据（由当前数据库导出，可重复执行）
-- 作品标题与简介均为中文；预览地址统一使用 Bilibili 视频 / 番剧资源，详情页内嵌播放器直接观看

-- 3.1 清理已移除的旧标签
DELETE FROM anime_genres WHERE genre_id IN (SELECT id FROM genres WHERE name IN ('动作','校园'));
DELETE FROM genres WHERE name IN ('动作','校园');

