(135,'三颗星彩色冒险','三颗星彩色冒险','上野公园里悄悄设立了一个总部。那里有三个国小女生——！没错，她们正是守护上野的正义团队“COLORS”！！结衣、小幸、琴叶三个人，今天也为了守护上野的和平，日夜（其实只到傍…','/covers/135.jpg','https://www.bilibili.com/video/BV1RW411B7qn','2018 冬','ANIME','FINISHED',0,0),
(136,'迷宫饭','迷宫饭','迷宫饭。是“吃”，还是“被吃”，这是一个问题。 在迷宫深处，莱欧斯眼看着炎龙吃掉了妹妹，自己在将死之际回到了地面。 尽管他想要马上再次挑战迷宫，但是钱和粮食都被留在了最深处…','/covers/136.png','https://www.bilibili.com/video/BV13w41157Fk','2024 冬','ANIME','FINISHED',0,0),
