(138,'机器人少女Z','机器人少女Z','故事发生在未来，“Z组合”平时在东京练马区大泉学园光子力町进行新型能源“光子能源”的宣传活动，偶尔将前来搞破坏的地下帝国的尖兵（机械兽少女们）揍飞（顺便发泄压力）。是日常搞…','/covers/138.jpg','https://www.bilibili.com/video/BV1ks411R7Rr','2014 冬','ANIME','FINISHED',0,0),
