(140,'电波女与青春男','电波女与青春男','故事的主角是将“青春点数”分配到自己的行动和相关的事情上、有时欢喜有时忧愁的少年丹羽真，及把被子卷在身上、自称外星人的“电波女”（却是美少女）的藤和艾莉欧。作品以这二人为中…','/covers/140.jpg','https://www.bilibili.com/video/BV19W411f7gp','2011 春','ANIME','FINISHED',0,0),
