(145,'迷途之子!!!!!','迷途之子!!!!!','高一的春末。羽丘女子学园的所有人都加入了乐队， 晚入学的爱音为了尽快融入班级，急急忙忙地寻找着乐队成员。 这时她得知，「羽丘的不可思议女孩」灯还没有加入乐队， 于是爱音不由…','/covers/145.png','https://www.bilibili.com/video/BV1Zu4y1B7DU','2024 秋','ANIME','FINISHED',0,0),
