(148,'CLANNAD ～AFTER STORY～','CLANNAD ～AFTER STORY～','在某个小镇，主角冈崎朋也因家庭因素成为不良少年，一直与春原阳平为伍，在光坂高校过着潦倒的生活，但冀望终有一天能够离开所在的小镇。某一天，他在学校坡道前发现了一个止步不前的女…','/covers/148.png','https://www.bilibili.com/video/BV1mW411Q73q','2008 秋','ANIME','FINISHED',0,0),
