(152,'黑子的篮球','黑子的篮球','黑子的篮球是藤卷忠俊的一部漫画作品，于08年12月开始连载。并已被改编成动画片。黑子的篮球是一部有关篮球的作品，讲述以篮球出名的帝光中学曾出了五位被称为奇迹世代的球员，但事实上…','/covers/152.jpg','https://www.bilibili.com/video/BV1Mx411A7nr','2012 春','ANIME','FINISHED',0,0),
(153,'强风吹拂','强风吹拂','夜晚。如同逃跑一般奔驰在城市中的藏原走。他的侧面，突然有辆自行车冲来。素不相识的男子，对阿走发问了。“喂！你很喜欢跑步吧！” 男子的名字是清濑灰二。 就这样，阿走在灰二的引导下…','/covers/153.png','https://www.bilibili.com/video/BV1AW411U7fn','2018 秋','ANIME','FINISHED',0,0),
