(156,'失忆投捕','失忆投捕','原作为连载于集英社《少年JUMP+》，应用内总阅读量超过2亿次的《失忆投捕》（原作·美川绘子）。2018年4月开始连载，凭借主角失忆的独特设定、富有魅力的角色、对高中棒球的写实…','/covers/156.png','https://www.bilibili.com/video/BV1aSd3YeEKa','2025 春','ANIME','FINISHED',0,0),
