-- 3.7 真实用户评论（用暂存表避免重复执行时重复插入）
DROP TEMPORARY TABLE IF EXISTS comment_seed;
CREATE TEMPORARY TABLE comment_seed (user_id BIGINT, anime_id BIGINT, content VARCHAR(1000), likes INT, created_at DATETIME);
INSERT INTO comment_seed(user_id, anime_id, content, likes, created_at) VALUES
(1,1,'第二季的节奏更稳了，超自然和青春期的碰撞依然让人惊喜。',42,'2026-11-25 10:05:42'),
(4,2,'温柔不是故事的终点，是角色终于敢往前走的那一步。',31,'2026-11-25 10:05:42'),
(2,3,'剧场版期待值拉满，希望把原作的张力完整搬上银幕。',28,'2026-11-25 10:05:42'),
(5,6,'越是慢慢看，越能理解时间留给每个人的重量。',55,'2026-11-25 10:05:42'),
(6,5,'宫廷谜案和少女成长交织得恰到好处，猫猫依然可爱。',37,'2026-11-25 10:05:42'),
(7,8,'每次重看都会发现新的细节，片尾那种怅然还是会击中我。',64,'2026-11-25 10:05:42'),
(41,9,'《进击的巨人》不是那种爽完就结束的作品，看完会想和朋友聊很久。',30,'2026-09-30 11:06:43'),
(34,9,'《进击的巨人》的配角写得很好，每个人都有自己的立场和温柔。',13,'2026-10-05 11:06:43'),
(27,9,'追《进击的巨人》的过程很舒服，节奏松紧得当，角色之间的互动也自然。',156,'2026-10-10 11:06:43'),
(20,9,'《进击的巨人》最打动我的不是剧情有多满，而是角色在关键时刻做出的选择。',139,'2026-10-15 11:06:43'),
(13,9,'看《进击的巨人》的时候一直在猜后续，结果被角色的选择惊喜到了。',122,'2026-10-20 11:06:43'),
(4,9,'《进击的巨人》让我重新喜欢上了追番这件事，期待后续展开。',105,'2026-10-25 11:06:43'),
(39,9,'一口气补完《进击的巨人》，最难忘的是结尾那种余韵。',88,'2026-10-30 11:06:43'),
(32,9,'《进击的巨人》有几场戏的留白很妙，比把话说满更有力量。',71,'2026-11-04 11:06:43'),
(25,9,'《进击的巨人》不是那种爽完就结束的作品，看完会想和朋友聊很久。',54,'2026-11-09 11:06:43'),
(18,9,'《进击的巨人》的配角写得很好，每个人都有自己的立场和温柔。',37,'2026-11-14 11:06:43'),
(11,9,'追《进击的巨人》的过程很舒服，节奏松紧得当，角色之间的互动也自然。',20,'2026-11-19 11:06:43'),
(1,9,'《进击的巨人》最打动我的不是剧情有多满，而是角色在关键时刻做出的选择。',3,'2026-11-24 11:06:43'),
(12,10,'《鬼灭之刃》把日常里的微小情绪拍得很真诚，细节控会喜欢。',43,'2026-09-27 11:06:43'),
(2,10,'《鬼灭之刃》的色调和镜头语言很统一，观看体验非常沉浸。',26,'2026-10-02 11:06:43'),
(38,10,'《鬼灭之刃》前半段铺得很稳，后半段的情绪释放也接住了。',9,'2026-10-07 11:06:43'),
(31,10,'原本只是想随便看看《鬼灭之刃》，结果一集接一集停不下来。',152,'2026-10-12 11:06:43'),
(24,10,'《鬼灭之刃》的画面完成度很高，几处长镜头单独截出来都能当壁纸。',135,'2026-10-17 11:06:43'),
(17,10,'《鬼灭之刃》最难得的是真诚，它没有为了热闹牺牲人物。',118,'2026-10-22 11:06:43'),
(10,10,'《鬼灭之刃》的场景美术很用心，背景里的小物件都经得起看。',101,'2026-10-27 11:06:43'),
(43,10,'《鬼灭之刃》的角色关系有层次，不是简单的阵营划分。',84,'2026-11-01 11:06:43'),
(36,10,'《鬼灭之刃》把日常里的微小情绪拍得很真诚，细节控会喜欢。',67,'2026-11-06 11:06:43'),
(29,10,'《鬼灭之刃》的色调和镜头语言很统一，观看体验非常沉浸。',50,'2026-11-11 11:06:43'),
(22,10,'《鬼灭之刃》前半段铺得很稳，后半段的情绪释放也接住了。',33,'2026-11-16 11:06:43'),
(15,10,'原本只是想随便看看《鬼灭之刃》，结果一集接一集停不下来。',16,'2026-11-21 11:06:43'),
(23,11,'《全职猎人》的底色是温柔的，哪怕故事里有冲突也不让人压抑。',56,'2026-09-24 11:06:43'),
