(11,7,'《铃芽之旅》的底色是温柔的，哪怕故事里有冲突也不让人压抑。',100,'2026-03-24 11:11:25'),
(1,7,'《铃芽之旅》的动作设计干脆利落，关键场面看完还想重播。',83,'2026-03-29 11:11:25'),
(12,8,'《你的名字。》的配角写得很好，每个人都有自己的立场和温柔。',123,'2026-01-30 11:11:25'),
(2,8,'追《你的名字。》的过程很舒服，节奏松紧得当，角色之间的互动也自然。',106,'2026-02-04 11:11:25'),
(38,8,'《你的名字。》最打动我的不是剧情有多满，而是角色在关键时刻做出的选择。',89,'2026-02-09 11:11:25'),
