INSERT INTO comments(user_id, anime_id, content, likes, created_at)
SELECT s.user_id, s.anime_id, s.content, s.likes, s.created_at FROM comment_seed s
JOIN anime a ON a.id = s.anime_id
WHERE NOT EXISTS (SELECT 1 FROM comments c WHERE c.user_id=s.user_id AND c.anime_id=s.anime_id AND c.content=s.content);
DROP TEMPORARY TABLE comment_seed;

