-- 3.10 清理下架作品与合并同一作品
-- 《你的名字。》重复条目 26 合并到 8
DELETE r FROM ratings r JOIN ratings t ON t.user_id = r.user_id AND t.anime_id = 8 WHERE r.anime_id = 26;
DELETE w FROM watchlist w JOIN watchlist t ON t.user_id = w.user_id AND t.anime_id = 8 WHERE w.anime_id = 26;
INSERT IGNORE INTO anime_genres(anime_id, genre_id) SELECT 8, genre_id FROM anime_genres WHERE anime_id = 26;
UPDATE ratings SET anime_id = 8 WHERE anime_id = 26;
UPDATE watchlist SET anime_id = 8 WHERE anime_id = 26;
UPDATE comments SET anime_id = 8 WHERE anime_id = 26;

