DELETE w FROM watchlist w JOIN watchlist t ON t.user_id = w.user_id AND t.anime_id = 15 WHERE w.anime_id = 42;
INSERT IGNORE INTO anime_genres(anime_id, genre_id) SELECT 15, genre_id FROM anime_genres WHERE anime_id = 42;
UPDATE ratings SET anime_id = 15 WHERE anime_id = 42;
UPDATE watchlist SET anime_id = 15 WHERE anime_id = 42;
UPDATE comments SET anime_id = 15 WHERE anime_id = 42;

