(35,158,'咪娅酱 的补番记录：《小马宝莉大电影》值得反复回味，角色与节奏都很有记忆点。',6,'2026-11-15 12:00:00'),
(36,158,'欧利弗 的补番记录：《小马宝莉大电影》值得反复回味，角色与节奏都很有记忆点。',0,'2026-11-15 12:00:00');
INSERT INTO comments(user_id, anime_id, content, likes, created_at)
SELECT s.user_id, s.anime_id, s.content, s.likes, s.created_at FROM interaction_comment_seed s
JOIN users u ON u.id = s.user_id
JOIN anime a ON a.id = s.anime_id
WHERE NOT EXISTS (SELECT 1 FROM comments c WHERE c.user_id = s.user_id AND c.anime_id = s.anime_id AND c.content = s.content);
DROP TEMPORARY TABLE interaction_comment_seed;
-- 3.15 漫评与社群种子数据（显式 ID，重复执行不会重复插入）
INSERT IGNORE INTO reviews(id, user_id, anime_id, title, content, score, likes, created_at) VALUES
(1,4,1,'当青春期遇见宇宙的裂缝','《胆大党 第二季》最迷人的地方，是它从来不把青春的笨拙藏起来。每一次大喊大叫背后，都有角色认真活着的证据，也有创作者对类型片节奏的精准把控。',10,342,'2026-11-20 20:30:00'),
(2,5,21,'热闹背后，角色都留着一口气','《咒术回战》把战斗写得很快，但真正留下来的是角色在战斗间隙的犹豫。热闹不是目的，那些没有说出口的失落，才让下一场对决有了重量。',9,218,'2026-11-19 21:10:00'),
(3,6,60,'排球落地之前','《排球少年!!》最厉害的不是把扣球画得多帅，而是让每一次传球都像一次信任的交付。比分之外，我们看到一群人如何把彼此的短板补成完整的队伍。',10,296,'2026-11-18 19:40:00'),
(4,7,136,'把冒险拍成一顿饭','《迷宫饭》把地下城变成厨房，也把怪物变成食谱。它表面上在讲吃，实际是在讲一支队伍如何用最日常的方式理解未知，幽默和残酷始终保持在同一张餐桌上。',9,187,'2026-11-17 22:05:00'),
(5,10,150,'无聊是青春最诚实的形状','《男子高中生的日常》把没有剧情的日子拍得理直气壮。那些突然认真起来的妄想，恰恰说明少年们还没学会把情绪包装成体面的样子，笑点因此格外干净。',9,164,'2026-11-16 20:15:00'),
(6,11,152,'传球比得分更像主角','《黑子的篮球》让存在感很弱的人成为叙事中心。它把篮球从天才表演改写成连接与分配，谁看见谁、谁愿意把球交出去，比最后一投更接近团队运动的本质。',8,143,'2026-11-15 21:25:00'),
(7,12,153,'跑步的时候，风会替人说话','《强风吹拂》没有把长跑拍成热血口号，而是让它成为十个人重新认识自己的过程。呼吸、步伐、疼痛和沉默一层层叠起来，最后抵达的不是冠军，是愿意继续向前。',10,311,'2026-11-14 20:50:00'),
(8,13,154,'天才也需要一个球场','《网球王子》把竞技写得像一场永不结束的自我介绍。夸张招式之外，真正推动故事的是少年们对变强的执念，以及每次被对手照见短板之后仍想上场的劲头。',8,126,'2026-11-13 19:35:00'),
(9,14,155,'冰面之上，失败也可以很漂亮','《金牌得主》把花滑拍成一次关于重新开始的长镜头。技术分、编排和教练的争执都只是外壳，最动人的是选手终于允许自己把摔倒也算进成长里。',9,205,'2026-11-12 21:40:00'),
(10,15,156,'忘记比分之后还记得队友','《失忆投捕》用失忆设定拆开运动番最熟悉的胜负叙事。当数据被清空，投手与捕手之间剩下的默契、玩笑和信任，反而成了最扎实的剧情支点。',9,178,'2026-11-11 20:20:00'),
(11,16,157,'成年人的身体也可以重新起飞','《体操武士》把中年危机和体操放在一起，产生了一种很温柔的反差。它不否认生活的疲惫，却相信身体重新学会跳跃时，人也会重新获得一点面对日常的勇气。',8,132,'2026-11-10 22:00:00'),
(12,44,158,'友谊魔法不是低龄的借口','《小马宝莉大电影》把冒险、歌舞和和解缝在一起，节奏明亮却不轻浮。六位主角各自犯错又彼此补位，让所谓友谊更像一套处理分歧的方法，而不是一句口号。',8,97,'2026-11-09 19:50:00');

