(1,'TOPIC','本季新番交换观感','不剧透地聊聊本周最惊喜的一集，也欢迎安利被低估的作品。','新番/观感','pink',2431,4,'2026-11-20 18:00:00'),
(2,'TOPIC','深夜放映：一起看老番','每周挑一部老番，从第一集开始重新体会当年的叙事节奏。','老番/放映','black',876,5,'2026-11-19 18:00:00'),
(3,'TOPIC','你的年度神作是哪部？','只选一部，并说说它为什么在一年之后仍然留在你这里。','年度/盘点','blue',1205,6,'2026-11-18 18:00:00'),
(4,'TOPIC','运动番为什么总能让人热血','是比赛、队友，还是最后一次起身？聊聊运动番真正击中你的瞬间。','运动/热血','pink',684,44,'2026-11-17 18:00:00'),
(5,'TOPIC','剧场版与 TV 版，你更偏爱哪种叙事','篇幅改变之后，角色与节奏会怎样变形？欢迎拿具体作品举例。','剧场版/叙事','blue',512,45,'2026-11-16 18:00:00'),
(6,'TOPIC','想为哪部作品写一首角色歌','如果给某个角色写一段旋律，你会选谁，又会把哪句台词放进副歌。','音乐/角色','black',329,46,'2026-11-15 18:00:00'),
(7,'GROUP','宇宙电波俱乐部','一起聊科幻设定、世界观考据与那些离现实很远的温柔。','科幻 / 奇幻','blue',8420,4,'2026-11-14 12:00:00'),
(8,'GROUP','少女漫放映室','从恋爱、治愈到成长，收藏每一段让人愿意重看的细腻关系。','恋爱 / 治愈','pink',5108,5,'2026-11-13 12:00:00'),
(9,'GROUP','作画观察协会','逐帧聊演出、构图与动作设计，欢迎带截图来一起拆解。','动画研究 / 作画','black',3662,6,'2026-11-12 12:00:00'),
(10,'GROUP','运动番应援团','排球、跑步、篮球、棒球都算，比赛之外也聊队伍里的人。','运动 / 热血','pink',2140,47,'2026-11-11 12:00:00'),
(11,'GROUP','深夜漫评写作组','把看完之后没散掉的感受写成一篇慢一点的文章。','漫评 / 写作','blue',1580,48,'2026-11-10 12:00:00'),
(12,'EVENT','《胆大党》连载放映会','今晚 21:00 一起连看两集，结束后用半小时交换第一印象。','今晚 21:00','pink',128,2,'2026-11-20 16:00:00');

